/// <summary>
/// Main class to process MarkupAuto recods transfer
/// </summary>
internal final class NDXMarkupAutoTransferProcess extends NDXTransferToD365 implements NDXTransferToD365Interface
{
    MarkupAutoTable lMarkupAutoTable;
    MarkupAutoLine lMarkupAutoLine;

    Niedax.AX.TableRecordModels.MarkupAutoTable markupAutoTable;
    Niedax.AX.TableRecordModels.MarkupAutoLine markupAutoLine;

}

Method.Source:
public void new()
{
    super();
    markupAutoTable = new Niedax.AX.TableRecordModels.MarkupAutoTable();
    markupAutoTable.D365ClassId = classIdGet(this);
    markupAutoTable.D365ClassName = classId2Name(markupAutoTable.D365ClassId);

    markupAutoLine = new Niedax.AX.TableRecordModels.MarkupAutoLine();
    markupAutoLine.D365ClassId = classIdGet(this);
    markupAutoLine.D365ClassName = classId2Name(markupAutoLine.D365ClassId);
}

/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public void startTransfer(Args _args)
{
    RecId responseMarkupTableRecId = 0; 
    super(_args);

    while select crosscompany lMarkupAutoTable
    {
        markupAutoTable.AccountCode = lmarkupAutoTable.AccountCode;
        markupAutoTable.AccountRelation = lmarkupAutoTable.AccountRelation;
        markupAutoTable.DlvModeCode = lmarkupAutoTable.DlvModeCode;
        markupAutoTable.DlvModeRelation = lmarkupAutoTable.DlvModeRelation;
        markupAutoTable.ItemCode = lmarkupAutoTable.ItemCode;
        markupAutoTable.ItemRelation = lmarkupAutoTable.ItemRelation;
        markupAutoTable.MarkupReturn = lmarkupAutoTable.MarkupReturn;
        markupAutoTable.ModuleCategory = lmarkupAutoTable.ModuleCategory;
        markupAutoTable.ModuleType = lmarkupAutoTable.ModuleType;
        markupAutoTable.ReturnRelation = lmarkupAutoTable.ReturnRelation;
        markupAutoTable.RetailConcessionFeeLegacy = lmarkupAutoTable.RetailConcessionFeeLegacy;
        markupAutoTable.SHA256HASH = lmarkupAutoTable.SHA256HASH;
        markupAutoTable.RetailAdvancedChargesDeliveryProrate = lmarkupAutoTable.RetailAdvancedChargesDeliveryProrate;
        markupAutoTable.RetailChannelCode = lmarkupAutoTable.RetailChannelCode;
        markupAutoTable.RetailChannelRelation = lmarkupAutoTable.RetailChannelRelation;
        markupAutoTable.Description = lmarkupAutoTable.Description;
        markupAutoTable.KCS_BosCustGroup2Alliance = lmarkupAutoTable.KCS_BosCustGroup2Alliance;

        markupAutoTable.DataAreaId = lmarkupAutoTable.DataAreaId;

        markupAutoTable.D365TableId = tableNum(MarkupAutoTable);
        markupAutoTable.D365TableName = tableId2PName(markupAutoTable.D365TableId);

        try
        {
            response = tableTransfer.transferTableRecordToD365(markupAutoTable);
        }
        catch 
        {
            response.Message = strFmt('transfer exception %1 ', markupAutoTable.ToString());
        }

        this.dispTransferInfo();

        if(response.Success && response.RecId > 0)
        {
            responseMarkupTableRecId = response.RecId;
            lMarkupAutoLine.clear();
            changecompany(lmarkupAutoTable.DataAreaId)
            {
                while select lMarkupAutoLine order by lMarkupAutoLine.LineNum
                    where lMarkupAutoLine.TableRecId == lMarkupAutoTable.RecId
                        &&  lMarkupAutoLine.TableTableId == lMarkupAutoTable.TableId
                {
                    markupAutoLine.CurrencyCode = lMarkupAutoLine.CurrencyCode;
                    markupAutoLine.CustomsAssessableValue_IN = lMarkupAutoLine.CustomsAssessableValue_IN;
                    markupAutoLine.FromAmount = lMarkupAutoLine.FromAmount;
                    markupAutoLine.Keep = lMarkupAutoLine.Keep;
                    markupAutoLine.LineNum = lMarkupAutoLine.LineNum;
                    markupAutoLine.MarkupCategory = lMarkupAutoLine.MarkupCategory;
                    markupAutoLine.MarkupCode = lMarkupAutoLine.MarkupCode;
                    markupAutoLine.MarkupCurrencyCode = lMarkupAutoLine.MarkupCurrencyCode;
                    markupAutoLine.McrReturnMarkup = lMarkupAutoLine.McrReturnMarkup;
                    markupAutoLine.ModuleCategory = lMarkupAutoLine.ModuleCategory;
                    markupAutoLine.ModuleType = lMarkupAutoLine.ModuleType;
                    markupAutoLine.NotionalCharges_In = lMarkupAutoLine.NotionalCharges_In;
                    markupAutoLine.NotionalPct_IN = lMarkupAutoLine.NotionalPct_IN;

                    markupAutoLine.TableRecId = responseMarkupTableRecId;

                    markupAutoLine.TableTableId = lMarkupAutoLine.TableTableId;
                    markupAutoLine.TaxGroup = lMarkupAutoLine.TaxGroup;
                    markupAutoLine.TaxItemGroup = lMarkupAutoLine.TaxItemGroup;
                    markupAutoLine.ToAmount = lMarkupAutoLine.ToAmount;
                    markupAutoLine.Txt = lMarkupAutoLine.Txt;
                    markupAutoLine.Value = lMarkupAutoLine.Value;
                    markupAutoLine.InventSiteId = lMarkupAutoLine.InventSiteId;
                    markupAutoLine.InventLocationId = lMarkupAutoLine.InventLocationId;
                    markupAutoLine.IsCompound = lMarkupAutoLine.IsCompound;
                    markupAutoLine.Sequence = lMarkupAutoLine.Sequence;
                    markupAutoLine.SpecificUnitSymbol = lMarkupAutoLine.SpecificUnitSymbol;
                    markupAutoLine.AVAFromDate = lMarkupAutoLine.AVAFromDate;
                    markupAutoLine.AVAToDate = lMarkupAutoLine.AVAToDate;

                    markupAutoLine.DataAreaId = lMarkupAutoLine.DataAreaId;
                    markupAutoLine.D365TableId = tableNum(MarkupAutoLine);
                    markupAutoLine.D365TableName = tableId2PName(markupAutoLine.D365TableId);

                    try
                    {
                        response = tableTransfer.transferTableRecordToD365(markupAutoLine);
                    }
                    catch
                    {
                        response.Message = strFmt('transfer exception %1 ', markupAutoLine.ToString());
                    }
                    this.dispTransferInfo();
                }
            }
        }
    }
}

/// <summary>
/// writes markupAutoTable to database
/// </summary>
/// <param name = "_record">markupAutoTable object</param>
private void writeMarkupAutoTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    markupAutoTable = _record;

    response.Message = strFmt("%1 %2 not created on %3", markupAutoTable.D365TableName
                    , markupAutoTable.ToString()
                    , this.environment);

    changecompany(markupAutoTable.DataAreaId)
    {
        MarkupAutoTable searchParameters;

        searchParameters.ModuleCategory    = markupAutoTable.moduleCategory;
        searchParameters.ModuleType        = markupAutoTable.moduleType;
        searchParameters.AccountCode       = markupAutoTable.accountCode;
        searchParameters.AccountRelation   = markupAutoTable.accountRelation;
        searchParameters.ItemCode          = markupAutoTable.itemCode;
        searchParameters.ItemRelation      = markupAutoTable.itemRelation;
        searchParameters.MarkupReturn      = markupAutoTable.markupReturn;
        searchParameters.DlvModeCode       = markupAutoTable.dlvModeCode;
        searchParameters.DlvModeRelation   = markupAutoTable.dlvModeRelation;

        searchParameters.RetailChannelCode = markupAutoTable.RetailChannelCode;
        searchParameters.RetailChannelRelation = markupAutoTable.RetailChannelRelation;
        searchParameters.ReturnRelation    = markupAutoTable.returnRelation;

        lMarkupAutoTable = MarkupAutoTable::findByNaturalKey(searchParameters, true);

        ttsbegin;
        lMarkupAutoTable.AccountCode = markupAutoTable.AccountCode;
        lMarkupAutoTable.AccountRelation = markupAutoTable.AccountRelation;
        lMarkupAutoTable.DlvModeCode = markupAutoTable.DlvModeCode;
        lMarkupAutoTable.DlvModeRelation = markupAutoTable.DlvModeRelation;
        lMarkupAutoTable.ItemCode = markupAutoTable.ItemCode;
        lMarkupAutoTable.ItemRelation = markupAutoTable.ItemRelation;
        lMarkupAutoTable.MarkupReturn = markupAutoTable.MarkupReturn;
        lMarkupAutoTable.ModuleCategory = markupAutoTable.ModuleCategory;
        lMarkupAutoTable.ModuleType = markupAutoTable.ModuleType;
        lMarkupAutoTable.ReturnRelation = markupAutoTable.ReturnRelation;

        lMarkupAutoTable.RetailConcessionFeeLegacy = markupAutoTable.RetailConcessionFeeLegacy;
        lMarkupAutoTable.SHA256HASH = markupAutoTable.SHA256HASH;
        lMarkupAutoTable.RetailAdvancedChargesDeliveryProrate = markupAutoTable.RetailAdvancedChargesDeliveryProrate;
        lMarkupAutoTable.RetailChannelCode = markupAutoTable.RetailChannelCode;
        lMarkupAutoTable.RetailChannelRelation = markupAutoTable.RetailChannelRelation;
        lMarkupAutoTable.Description = markupAutoTable.Description;
        lMarkupAutoTable.KCS_BosCustGroup2Alliance = markupAutoTable.KCS_BosCustGroup2Alliance;

        lMarkupAutoTable.write();
        ttscommit;

        if(lMarkupAutoTable)
        {
            response.Success = true;
            response.Message = strFmt("%1 %2 created on %3", tableId2Name(lMarkupAutoTable.TableId)
                , markupAutoTable.ToString()
                , this.environment);
        }

        response.RecId = lMarkupAutoTable.RecId;
    }
}

/// <summary>
/// writes MarkupAutoLine to database
/// </summary>
/// <param name = "_record">MarkupAutoLine object</param>
private void writeMarkupAutoLine(Niedax.AX.TableRecordModels.TableRecord _record)
{
    markupAutoLine = _record;

    response.Message = strFmt("%1 %2 not created on %3", markupAutoLine.D365TableName
                    , markupAutoLine.ToString()
                    , this.environment);

    changecompany(markupAutoLine.DataAreaId)
    {
        lMarkupAutoTable.clear();
        lMarkupAutoLine.clear();

        lMarkupAutoTable = MarkupAutoTable::findByRecIdAndTableId(markupAutoLine.TableRecId, markupAutoLine.TableTableId);

        if(!lMarkupAutoTable)
        {
            throw error(strFmt("No MarkaupAutoTable record found RecId %1 tableid %2 ", markupAutoLine.TableRecId, markupAutoLine.TableTableId));
        }

        lMarkupAutoLine = MarkupAutoLine::findByTableRecIdTableIdLineNum(markupAutoLine.TableRecId, markupAutoLine.TableTableId, markupAutoLine.LineNum, true);

        ttsbegin;
        lMarkupAutoLine.CurrencyCode = markupAutoLine.CurrencyCode;
        lMarkupAutoLine.CustomsAssessableValue_IN = markupAutoLine.CustomsAssessableValue_IN;
        lMarkupAutoLine.FromAmount = markupAutoLine.FromAmount;
        lMarkupAutoLine.Keep = markupAutoLine.Keep;
        lMarkupAutoLine.LineNum = markupAutoLine.LineNum;
        lMarkupAutoLine.MarkupCategory = markupAutoLine.MarkupCategory;
        lMarkupAutoLine.MarkupCode = markupAutoLine.MarkupCode;
        lMarkupAutoLine.MarkupCurrencyCode = markupAutoLine.MarkupCurrencyCode;
        lMarkupAutoLine.McrReturnMarkup = markupAutoLine.McrReturnMarkup;
        lMarkupAutoLine.ModuleCategory = markupAutoLine.ModuleCategory;
        lMarkupAutoLine.ModuleType = markupAutoLine.ModuleType;
        lMarkupAutoLine.NotionalCharges_In = markupAutoLine.NotionalCharges_In;
        lMarkupAutoLine.NotionalPct_IN = markupAutoLine.NotionalPct_IN;
        lMarkupAutoLine.TableRecId = markupAutoLine.TableRecId;
        lMarkupAutoLine.TableTableId = markupAutoLine.TableTableId;
        lMarkupAutoLine.TaxGroup = markupAutoLine.TaxGroup;
        lMarkupAutoLine.TaxItemGroup = markupAutoLine.TaxItemGroup;
        lMarkupAutoLine.ToAmount = markupAutoLine.ToAmount;
        lMarkupAutoLine.Txt = markupAutoLine.Txt;
        lMarkupAutoLine.Value = markupAutoLine.Value;
        lMarkupAutoLine.InventSiteId = markupAutoLine.InventSiteId;
        lMarkupAutoLine.InventLocationId = markupAutoLine.InventLocationId;
        lMarkupAutoLine.IsCompound = markupAutoLine.IsCompound;
        lMarkupAutoLine.Sequence = markupAutoLine.Sequence;
        lMarkupAutoLine.SpecificUnitSymbol = markupAutoLine.SpecificUnitSymbol;
        lMarkupAutoLine.AVAFromDate = markupAutoLine.AVAFromDate;
        lMarkupAutoLine.AVAToDate = markupAutoLine.AVAToDate;

        lMarkupAutoLine.write();
        ttscommit;

        if(lMarkupAutoLine)
        {
            response.Success = true;
            response.Message = strFmt("%1 %2 created on %3", tableId2Name(lMarkupAutoLine.TableId)
                , markupAutoLine.ToString()
                , this.environment);
        }

        response.RecId = lMarkupAutoLine.RecId;
    }
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    switch(tableName2Id(_record.D365TableName))
    {
        case tableNum(MarkupAutoTable):
            this.writeMarkupAutoTable(_record);
            break;
        case tableNum(MarkupAutoLine):
            this.writeMarkupAutoLine(_record);
            break;
    }

    return response;
}
